/* eslint-disable no-unused-vars */
// Service worker will be generated by workbox build
self.addEventListener('install', function(event) {
  self.skipWaiting();
});
self.addEventListener('fetch', function(event) {
  // Network-only for now
});

// sw.js - Cache content for offline use
self.addEventListener('fetch', (event) => {
  if (event.request.url.includes('/api/content')) {
    event.respondWith(
      caches.open('content-cache').then(cache => {
        return fetch(event.request).then(response => {
          cache.put(event.request, response.clone());
          return response;
        }).catch(() => {
          return cache.match(event.request);
        });
      })
    );
  }
});
// sw.js - Add these event listeners
self.addEventListener('message', function(event) {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

self.addEventListener('activate', function(event) {
  event.waitUntil(
    caches.keys().then(function(cacheNames) {
      return Promise.all(
        cacheNames.map(function(cacheName) {
          // Delete old caches
          if (cacheName.startsWith('lis-') && cacheName !== 'lis-v1') {
            return caches.delete(cacheName);
          }
        })
      );
    }).then(function() {
      // Claim clients
      return self.clients.claim();
    })
  );
});